A = set(range(2000))  # A = {0, 1, ..., 1999}
B = set(range(2016))  # B = {0, 1, ..., 2015}
tolerance = 1000
K = 0

for m in A:
    count_m = 0
    for n in B:
        if abs(m - n) <= tolerance:
            count_m += 1
    K += count_m

print(K)
